// Scene drawing
function path(points,fill){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fillStyle=fill;ctx.fill()}
function ellipse(x,y,rx,ry,color){ctx.fillStyle=color;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function tree(x,y,s,layer=0){const sway=Math.sin(state.time*.001+x)*2;ctx.save();ctx.translate(x,y);ctx.scale(s,s);ellipse(0,0,26,6,'#08181855');ctx.fillStyle=layer?'#243c38':'#152b2a';ctx.beginPath();ctx.moveTo(-2,0);ctx.lineTo(-2,-53);ctx.lineTo(-8,-57);ctx.lineTo(1,-60);ctx.lineTo(5,-52);ctx.lineTo(4,0);ctx.fill();for(let i=0;i<4;i++){let yy=-29-i*14;ctx.beginPath();ctx.moveTo(sway,yy-32);ctx.quadraticCurveTo(-31,yy-5,-25,yy+4);ctx.quadraticCurveTo(0,yy-2,26,yy+4);ctx.quadraticCurveTo(32,yy-4,sway,yy-32);ctx.fillStyle=layer?(i%2?'#314943':'#3b5b4b'):(i%2?'#1e3a34':'#27483c');ctx.fill();ctx.strokeStyle='#b9cc8a16';ctx.lineWidth=1;ctx.stroke();}if((Math.floor(x*3)%4)===0){ellipse(sway-10,-50,2,2,'#d7c477');ellipse(sway+13,-35,1.5,1.5,'#b3d9b2')}ctx.restore()}
function drawPerson(x,y){ctx.save();ctx.translate(x,y);const bounce=state.walk?Math.sin(state.time*.018)*2:0;ctx.translate(0,bounce);ellipse(0,2,21,7,'#0614168a');if(state.attacking>0){ctx.strokeStyle=`rgba(201,238,193,${state.attacking*.45})`;ctx.lineWidth=3;ctx.beginPath();ctx.arc(4,-17,35,-1.7,1.3);ctx.stroke()}
// robe and silhouette
path([[-12,-11],[-9,-29],[-4,-35],[5,-34],[11,-24],[13,-7],[19,0],[12,3],[-13,3],[-20,0],[-13,-3]],'#b9aa78');path([[-10,-11],[-7,-29],[0,-31],[7,-24],[9,-7],[15,0],[-13,1],[-17,-1]],'#345d56');path([[-5,-31],[0,-24],[7,-29],[9,-4],[0,-1],[-7,-6]],'#d2c28e');ellipse(0,-39,8,9,'#e1c8a0');ctx.fillStyle='#192725';ctx.beginPath();ctx.arc(0,-42,9,Math.PI,0);ctx.lineTo(8,-38);ctx.quadraticCurveTo(0,-44,-8,-38);ctx.fill();ctx.strokeStyle='#d9c484';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(5,-23);ctx.lineTo(23,-47);ctx.stroke();ctx.strokeStyle='#ecdfa8';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(22,-48);ctx.lineTo(29,-57);ctx.stroke();ctx.restore()}
function drawWolf(x,y){ctx.save();ctx.translate(x,y);const bob=Math.sin(state.time*.006)*2;ctx.translate(0,bob);ellipse(0,3,25,7,'#07141488');ctx.fillStyle='#4b5950';ctx.beginPath();ctx.moveTo(-22,-7);ctx.lineTo(-17,-18);ctx.lineTo(-3,-22);ctx.lineTo(8,-17);ctx.lineTo(17,-22);ctx.lineTo(24,-17);ctx.lineTo(19,-8);ctx.lineTo(22,-3);ctx.lineTo(10,-1);ctx.lineTo(6,-6);ctx.lineTo(-6,-4);ctx.lineTo(-15,0);ctx.lineTo(-25,-2);ctx.closePath();ctx.fill();ctx.fillStyle='#52665a';ctx.beginPath();ctx.moveTo(-14,-16);ctx.lineTo(-20,-28);ctx.lineTo(-8,-21);ctx.fill();ctx.beginPath();ctx.moveTo(3,-18);ctx.lineTo(8,-29);ctx.lineTo(12,-18);ctx.fill();ellipse(17,-15,2,2,'#f1bc72');ctx.strokeStyle='#c8e0b488';ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,-13,28,Math.PI,Math.PI*1.82);ctx.stroke();ctx.restore()}
function render(){const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;state.time++;ctx.clearRect(0,0,w,h);let sky=ctx.createLinearGradient(0,0,0,h);sky.addColorStop(0,'#1c3038');sky.addColorStop(.4,'#40564d');sky.addColorStop(1,'#192e29');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);
// moon glow and stars
const mx=w*.72,my=h*.24;let glow=ctx.createRadialGradient(mx,my,5,mx,my,180);glow.addColorStop(0,'#e4d7a928');glow.addColorStop(1,'#d6d3a000');ctx.fillStyle=glow;ctx.fillRect(mx-180,my-180,360,360);ellipse(mx,my,28,28,'#e6ddb5');ellipse(mx+11,my-6,26,27,'#36484a');for(let i=0;i<30;i++){let sx=(i*173+31)%w,sy=(i*79+19)%(h*.42);ctx.fillStyle=`rgba(232,228,190,${.16+.2*Math.sin(state.time*.01+i)})`;ctx.fillRect(sx,sy,1.5,1.5)}
// distant mountain silhouettes
path([[0,h*.53],[w*.13,h*.31],[w*.23,h*.46],[w*.41,h*.25],[w*.56,h*.47],[w*.72,h*.29],[w*.88,h*.49],[w,h*.34],[w,h*.74],[0,h*.75]],'#283b3c');path([[0,h*.61],[w*.18,h*.43],[w*.33,h*.59],[w*.5,h*.39],[w*.67,h*.57],[w*.85,h*.41],[w,h*.56],[w,h*.79],[0,h*.8]],'#304943');
// distant waterfall, lake
const wx=w*.74,wy=h*.43;ctx.fillStyle='#88c8bf40';ctx.beginPath();ctx.moveTo(wx-21,wy);ctx.lineTo(wx+14,wy);ctx.lineTo(wx+25,h*.71);ctx.lineTo(wx-35,h*.71);ctx.fill();for(let i=0;i<4;i++){ctx.strokeStyle=`rgba(199,226,207,${.14+Math.sin(state.time*.03+i)*.04})`;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(wx-12+i*8,wy+8);ctx.lineTo(wx-18+i*11,h*.68);ctx.stroke()}
let ground=ctx.createLinearGradient(0,h*.52,0,h);ground.addColorStop(0,'#435744');ground.addColorStop(.32,'#354c3c');ground.addColorStop(1,'#192d29');ctx.fillStyle=ground;ctx.fillRect(0,h*.52,w,h*.48);
// winding path
path([[w*.4,h],[w*.45,h*.68],[w*.51,h*.58],[w*.56,h*.55],[w*.61,h*.57],[w*.59,h*.62],[w*.54,h*.66],[w*.52,h*.76],[w*.58,h]],'#83785a');path([[w*.4,h],[w*.45,h*.69],[w*.51,h*.6],[w*.56,h*.57],[w*.6,h*.58],[w*.56,h*.63],[w*.52,h*.69],[w*.51,h*.78],[w*.55,h]],'#a19570');
// ground stones, grass flecks
for(let i=0;i<54;i++){const x=((i*197+state.x*4)% (w+30)+w+30)%(w+30)-15,y=h*.58+(i*61%(h*.41));ctx.fillStyle=i%3?'#aab78230':'#d7c37a38';ctx.beginPath();ctx.ellipse(x,y,1+(i%3),.8,0,0,6.3);ctx.fill()}
// framing forest
for(let i=0;i<9;i++){let x=i*w/8;let yy=h*(.61+((i*37)%11)/100);tree(x,yy,.74+(i%3)*.14,1)}for(let i=0;i<7;i++){let x=i*w/6+18;let yy=h*(.84+((i*13)%8)/100);tree(x,yy,.9+(i%3)*.23,0)}
// spirit-lup nearby, fireflies
const ex=w*.59+Math.sin(state.time*.002)*4,ey=h*.69; if(state.enemyAlive)drawWolf(ex,ey);else{ctx.fillStyle='#d5cc9a66';ctx.beginPath();ctx.arc(ex,ey-10,15+Math.sin(state.time*.05)*5,0,6.28);ctx.fill()}
for(let i=0;i<15;i++){let x=(i*103+Math.sin(state.time*.013+i*8)*14+w)%(w),y=h*(.38+(i*47%(h*.54))/h);let a=.25+.45*Math.sin(state.time*.035+i);ctx.fillStyle=`rgba(191,224,153,${Math.max(0,a)})`;ctx.shadowColor='#d6efad';ctx.shadowBlur=8;ctx.beginPath();ctx.arc(x,y,1.2,0,6.3);ctx.fill()}ctx.shadowBlur=0;
// player
let px=w*.5,py=h*.73;drawPerson(px,py);
// cultivated aura
if(state.meditating||state.rank>0){ctx.strokeStyle=`rgba(154,229,182,${.16+Math.sin(state.time*.06)*.06})`;ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(px,py-5,35+Math.sin(state.time*.04)*2,49,0,0,6.28);ctx.stroke()}
for(let i=state.particles.length-1;i>=0;i--){let p=state.particles[i];p.x+=p.vx;p.y+=p.vy;p.life--;ctx.globalAlpha=clamp(p.life/35,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,6.28);ctx.fill();ctx.globalAlpha=1;if(p.life<=0)state.particles.splice(i,1)}requestAnimationFrame(render)}
function burst(color='#d5e7a3',n=14){for(let i=0;i<n;i++)state.particles.push({x:canvas.clientWidth*.5+rand(-12,12),y:canvas.clientHeight*.73-22+rand(-12,12),vx:rand(-2.2,2.2),vy:rand(-2.8,.4),life:rand(18,38),size:rand(1,3),color})}

