function burst(color='#d5e7a3',n=14){for(let i=0;i<n;i++)state.particles.push({x:canvas.clientWidth*.5+rand(-12,12),y:canvas.clientHeight*.73-22+rand(-12,12),vx:rand(-2.2,2.2),vy:rand(-2.8,.4),life:rand(18,38),size:rand(1,3),color})}
const held=new Set();
function move(dir){const speed=4;state.walk=1;if(dir==='up')state.y-=speed;if(dir==='down')state.y+=speed;if(dir==='left')state.x-=speed;if(dir==='right')state.x+=speed;state.x=clamp(state.x,-999,999);state.y=clamp(state.y,-999,999)}
function attack(){if(!state.enemyAlive){toast('Așteaptă întoarcerea spiritului-lup.');return}state.attacking=1;setTimeout(()=>state.attacking=0,170);state.enemyHp-=12;burst('#ead58e',10);if(state.enemyHp<=0)defeatEnemy();updateUI()}
function qiStrike(){if(state.qi<25){toast('Ai nevoie de 25 qi pentru tehnică.');return}if(state.skillCd>0){toast('Tehnica se reîncarcă.');return}if(!state.enemyAlive){toast('Nu există o țintă în apropiere.');return}state.qi-=25;state.skillCd=150;state.enemyHp-=32;burst('#9fe5c4',24);state.attacking=1;setTimeout(()=>state.attacking=0,260);log('Lovitura de jad a străpuns apărarea spiritului!','good');if(state.enemyHp<=0)defeatEnemy();updateUI()}
function defeatEnemy(){state.enemyAlive=false;state.enemyRespawn=170;state.defeated++;state.xp+=35;state.stones+=rand(0,1)>.38?4:6;state.qi=Math.min(state.maxQi,state.qi+12);if(Math.random()<.35)state.herbs++;burst('#d7edb4',30);toast('Spirit-lup învins · +35 XP · pietre spirituale');log('Spirit-lup învins. Ai cules pietre spirituale.','good');if(state.defeated===3){state.stones+=25;state.herbs+=2;toast('Misiune împlinită! Recompensă: 25 pietre, 2 ierburi');log('Misiune împlinită! Cercetează calea cultivării.','sys');document.getElementById('questTitle').textContent='O cale fără sfârșit';document.getElementById('questCopy').textContent='Misiune împlinită. Cultivă qi-ul și urcă spre nemurire.';document.querySelector('.quest-progress span').textContent='Misiune';document.getElementById('questCount').textContent='✓';}if(state.xp>=state.nextXp){state.xp-=state.nextXp;state.level++;state.nextXp+=60;state.maxHp+=10;state.hp=state.maxHp;toast(`Nivel ${state.level}! Viața maximă a crescut.`);log(`Ai atins nivelul ${state.level}.`,`good`)}updateUI();save()}
function meditate(){state.meditating=!state.meditating;toast(state.meditating?'Intri în meditație. Qi-ul se adună.':'Ai încheiat meditația.');log(state.meditating?'Respiră lent. Simți qi-ul curgând prin meridiane.':'Ai revenit din meditație.','good');if(state.meditating)burst('#a2ebc5',12);updateUI()}
function breakthrough(){if(state.qi<state.maxQi){toast(`Ai nevoie de ${state.maxQi} qi pentru străpungere.`);return}if(state.rank>=ranks.length-1){toast('Ai atins pragul suprem cunoscut!');return}state.qi=0;state.rank++;state.maxQi+=25;state.maxHp+=15;state.hp=state.maxHp;state.stones+=10;burst('#d9f6be',44);toast(`Străpungere reușită · ${ranks[state.rank]}!`);log(`Străpungere! Ai urcat la ${ranks[state.rank]}.`,`good`);updateUI();save();openModal('cultivation')}
function useHerb(){if(state.herbs<1){toast('Nu mai ai ierburi vindecătoare.');return}if(state.hp>=state.maxHp){toast('Viața ta este deja plină.');return}state.herbs--;state.hp=Math.min(state.maxHp,state.hp+35);toast('Ai folosit Iarba de rouă · +35 viață');burst('#b0e8a9',10);updateUI();save();openModal('inventory')}
function useElixir(){if(state.elixirs<1){toast('Nu mai ai elixire.');return}state.elixirs--;state.qi=Math.min(state.maxQi,state.qi+40);toast('Elixir de jad · +40 qi');burst('#93e9d0',14);updateUI();save();openModal('inventory')}
const backdrop=document.getElementById('modalBackdrop');
function openModal(which){let title='',sub='',html='';if(which==='character'){title='Călătorul rătăcit';sub=`Nivel ${state.level} · ${ranks[Math.min(state.rank,ranks.length-1)]}`;html=`<div class="stat-grid"><div class="stat"><label>Viață</label><strong>${Math.ceil(state.hp)} / ${state.maxHp}</strong></div><div class="stat"><label>Qi spiritual</label><strong>${Math.floor(state.qi)} / ${state.maxQi}</strong></div><div class="stat"><label>Experiență</label><strong>${state.xp} / ${state.nextXp} XP</strong></div><div class="stat"><label>Pietre spirituale</label><strong>✦ ${state.stones}</strong></div><div class="stat"><label>Putere</label><strong>${12+state.rank*3} ATK</strong></div><div class="stat"><label>Spirite învinse</label><strong>${state.defeated}</strong></div></div><div class="cultivation-box" style="margin-top:13px"><h3>Jurnalul călătorului</h3><p>O lume persistentă de explorat? Deocamdată, valea îți este casă. Învinge spirite, adună resurse și fă-ți loc pe calea nemuririi.</p></div>`}
if(which==='inventory'){title='Desaga călătorului';sub=`Pietre spirituale: ✦ ${state.stones}`;html=`<div class="item-list"><div class="item"><span class="item-icon">🌿</span><div class="item-info"><div class="item-name">Iarbă de rouă</div><div class="item-desc">Restaurează 35 puncte de viață.</div></div><span class="item-count">× ${state.herbs}</span></div><div class="item"><span class="item-icon">🧪</span><div class="item-info"><div class="item-name">Elixir de jad</div><div class="item-desc">Restaurează 40 qi spiritual.</div></div><span class="item-count">× ${state.elixirs}</span></div><div class="item"><span class="item-icon">✦</span><div class="item-info"><div class="item-name">Piatră spirituală</div><div class="item-desc">Monedă folosită de cultivatori.</div></div><span class="item-count">× ${state.stones}</span></div></div><button class="wide-btn" id="useHerb" ${state.herbs<1||state.hp>=state.maxHp?'disabled':''}>Folosește iarbă de rouă</button><button class="wide-btn" id="useElixir" style="margin-top:7px" ${state.elixirs<1||state.qi>=state.maxQi?'disabled':''}>Bea elixir de jad</button>`}
if(which==='cultivation'){title='Arta cultivării';sub='Respiră. Ascultă. Depășește limitele muritorului.';html=`<div class="cultivation-box"><h3>${ranks[Math.min(state.rank,ranks.length-1)]}</h3><p>Adună qi meditând în vale sau învingând spirite. Când meridianele sunt pline, încearcă o străpungere pentru a-ți spori puterea și a descoperi un nou tărâm.</p><div class="bar qibar" style="margin-top:14px;height:7px"><i style="width:${100*state.qi/state.maxQi}%"></i></div><div class="bar-caption"><span>Qi acumulat</span><span>${Math.floor(state.qi)} / ${state.maxQi}</span></div></div><div class="stat-grid"><div class="stat"><label>Tărâm actual</label><strong>${state.rank+1}</strong></div><div class="stat"><label>Următoarea străpungere</label><strong>+15 viață · +10 pietre</strong></div></div><button class="wide-btn" id="breakthrough" ${state.qi<state.maxQi||state.rank>=ranks.length-1?'disabled':''}>✧ Străpunge tărâmul</button><button class="wide-btn" id="meditateBtn" style="margin-top:7px;background:${state.meditating?'linear-gradient(135deg,#455e52,#668b71)':''}">${state.meditating?'Oprește meditația':'☯ Începe meditația'}</button>`}
if(which==='techniques'){title='Tehnici spirituale';sub='Puterea ta crește odată cu tărâmul.';html=`<div class="technique"><div class="tech-icon">⚔</div><div><b>Tăietura călătorului</b><p>O lovitură sigură, care provoacă 12 daune. Nu costă qi.</p></div></div><div class="technique"><div class="tech-icon">✧</div><div><b>Lovitura de jad</b><p>Condensează qi-ul într-un arc devastator. Provoacă 32 daune și costă 25 qi. Reîncărcare: 2,5 secunde.</p></div></div><div class="technique"><div class="tech-icon">☯</div><div><b>Meditația nemuritorului</b><p>Ține <span class="key">E</span> sau activeaz-o din cultivare pentru a aduna 8 qi și 1 viață la fiecare câteva clipe.</p></div></div><button class="wide-btn" id="techAttack">⚔ Folosește lovitura de jad</button>`}
document.getElementById('modalTitle').textContent=title;document.getElementById('modalSub').textContent=sub;document.getElementById('modalContent').innerHTML=html;backdrop.classList.add('open');backdrop.dataset.modal=which;document.querySelectorAll('[data-modal]').forEach(b=>b.classList.toggle('active',b.dataset.modal===which));document.getElementById('useHerb')?.addEventListener('click',useHerb);document.getElementById('useElixir')?.addEventListener('click',useElixir);document.getElementById('breakthrough')?.addEventListener('click',breakthrough);document.getElementById('meditateBtn')?.addEventListener('click',()=>{meditate();openModal('cultivation')});document.getElementById('techAttack')?.addEventListener('click',()=>{closeModal();qiStrike()})}
